steps.script:
var dd = tree.root.get_node_or_null("/root/DisembarkDialog")
if dd == null:
	return false
dd.get_ok_button().pressed.emit()
return true

var wb = GameState.get_unit("U_WARBOSS_T")
var m = wb.get("models", [])
if m.is_empty():
	return false
return m[0].get("position", null) != null

var m = tree.root.get_node("Main")
var br = m.get_node("BoardRoot")
var out = []
for nm in ["MoveRangeVisual", "MovementERVisual", "MovementCoherencyVisual"]:
	var n = br.get_node_or_null(nm)
	out.append(-1 if n == null else n.get_child_count())
m.set_meta("overlay_counts", str(out))
return out[2] == 0 and out[0] >= 0 and out[1] > 0

# Nothing was LOST by deleting the static rings: the P3-116 drag preview is
# the live coherency affordance - a line from the carried ghost to every other
# model in the unit, green when that mate is inside coherency and red when it
# is not, plus a status label riding on the ghost.
var m = tree.root.get_node("Main")
var gv = m.get_node_or_null("BoardRoot/MovementGhostVisual")
if gv == null or gv.get_child_count() == 0:
	return "no ghost"
var ghost = gv.get_child(0)
if not ("coherency_lines_data" in ghost):
	return "ghost has no coherency_lines_data"
var lines = ghost.coherency_lines_data
var lbl = gv.get_node_or_null("CoherencyStatusLabel")
m.set_meta("coh_probe", "lines=%d status=%s label=%s" % [lines.size(), str(ghost.coherency_status_text), "<none>" if lbl == null else lbl.text])
if lines.size() < 9:
	return "only %d coherency lines for a 10-model mob" % lines.size()
var in_range := 0
for l in lines:
	if bool(l.get("in_coherency", false)):
		in_range += 1
if in_range < 1:
	return "no mate reported in coherency"
return "ok"

var phase = PhaseManager.get_current_phase_instance()
var md = phase.get_active_move_data("U_BATTLEWAGON_T")
var dists = md.get("model_distances", {})
for k in dists:
	return float(dists[k])
return -1.0

var o = tree.root.get_node("/root/TutorialOverlay")
var t = o.current_body_text()
return t.contains("[Q]") and t.contains("[E]") and t.contains("costs no inches")

var phase = PhaseManager.get_current_phase_instance()
var md = phase.get_active_move_data("U_BATTLEWAGON_T")
var dists = md.get("model_distances", {})
for k in dists:
	return float(dists[k])
return -1.0
